with d as (select value r from jsonb_array_elements($q$[{"notes":["Make a double batch and freeze half in a container; they'll keep for a month and reheat beautifully on the stove.","If you can't find lard, use neutral oil or a little butter, though lard gives them the best flavour.","Serve alongside arepas, white rice, or grilled meat.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages)."],"id":"a07692d4-ff36-4c9f-91b0-ec860aeb30c4"},{"notes":["Make it ahead: Laabda tastes even better the next day. Cool, cover, and refrigerate for up to 3 days, then reheat gently on the stove.","Scale it up: This recipe doubles easily for big family gatherings. Use a larger pot and add 30 minutes to the braising time.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the ghee in a large heavy-bottomed pot over medium-high heat. Working in batches, brown the beef on all sides, about 3 minutes per side. Transfer to a plate."},{"text":"Add the sliced onions to the pot and cook, stirring often, until deep golden and caramelized, about 20 minutes. This takes patience, let them colour properly for the sweetness."},{"text":"Add the minced garlic and cook for 1 minute until fragrant."},{"text":"Stir in the cardamom, cinnamon, cloves, turmeric, salt and pepper. Cook for 1 minute."},{"text":"Add the tomato paste and stir to coat the onions, cooking for 2 minutes."},{"text":"Return the beef to the pot along with the water and bay leaves. Bring to a simmer, then reduce heat to low, cover, and braise for 2½ to 3 hours, stirring occasionally. The meat is ready when it's very tender and breaks apart easily, and the sauce is rich and thickened."},{"text":"Taste and adjust seasoning. Serve hot with rice or flatbread."}],"id":"17365db3-20b4-4d9f-9645-4f10a8debb4f"},{"diets":["vegetarian","no-gluten"],"steps":[{"text":"Char the poblanos directly over a gas flame or under a hot grill, turning with tongs, until the skin is blackened all over, about 8 minutes. Place them in a plastic bag, seal it, and let them steam for 5 minutes."},{"text":"Peel off the blackened skin under cool running water. Remove the stem and seeds, then chop the poblano flesh into bite-sized pieces."},{"text":"Heat the oil in a large frying pan over medium heat. Add the onion and cook, stirring, until softened, about 4 minutes. Add the garlic and cook for 1 minute more."},{"text":"Reduce the heat to low. Add the Oaxaca cheese and cheddar in handfuls, stirring constantly until melted and smooth, about 5 minutes. The cheese should be creamy and flowing."},{"text":"Fold in the roasted poblano pieces. Taste and season with salt and pepper."},{"text":"Transfer to a warm serving dish and serve immediately with hot tortilla chips on the side."}],"id":"5eb15f12-a442-4a2d-957b-a9d2aa788fd7"},{"notes":["Olluco releases starch as it cooks, which naturally thickens the sauce. Don't rush it, the longer you simmer, the creamier it becomes.","Make it ahead: this dish tastes even better the next day. Reheat gently over low heat with a splash of milk or water."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the garlic and ají amarillo paste, stirring constantly to combine, about 1 minute. The mixture should be fragrant and bright yellow."},{"text":"Add the olluco, cumin, salt and pepper. Stir to coat the tubers in the ají mixture, about 2 minutes."},{"text":"Pour in just enough water to barely cover the olluco, about 300 ml. Bring to a simmer, then reduce heat to medium-low and cover, cooking until the olluco is tender when pierced with a knife."},{"text":"Cook for 20 minutes, until the olluco is very tender and the liquid has reduced slightly. Stir occasionally to prevent sticking."},{"text":"Pour in the milk and gently stir. Add the crumbled queso fresco and fold in carefully until it begins to melt into the sauce, about 3 minutes."},{"text":"Taste and adjust salt and pepper. The sauce should be creamy and the tubers very soft. Serve hot, scattered with coriander if you like."}],"id":"0159a90f-9c62-46af-a2b0-bdae4b45d2ae"},{"notes":["Use fresh wide rice noodles (from the chilled aisle) for the best texture, they're done the moment they're hot.","The heat matters: your wok needs to be smoking hot when the garlic goes in. This keeps the chicken from stewing.","Add the basil right at the end so it stays bright and fragrant.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"8be812a8-e6b8-4b12-9967-feaed671a86c"},{"notes":["Tripe is sold cleaned in most butchers, ask them to confirm it's ready to cook. If you find it tough after 30 minutes, keep simmering until it breaks down easily with a fork.","This keeps well in the fridge for 2 days and tastes better reheated the next day."],"id":"6b3e8ba5-eb48-4b78-835c-f5c3d5c4b849"},{"notes":["The chillies can be charred and peeled up to 4 hours ahead; keep them in a covered container in the fridge until you're ready to stuff them.","If you can't find Oaxaca cheese, fresh mozzarella (torn into chunks) or even grated Oaxaca from a package will work, the key is using cheese that melts easily.","The tomato sauce can be made ahead and reheated gently just before serving."],"id":"4006f058-0f3a-4444-bc91-c92ee3e5a121"},{"notes":["Labskaus is best made with cooked corned beef from a deli or tin. If using homemade, cook it until very tender, then cool before dicing.","Use waxy potatoes like kipfler or baby potatoes; they hold their shape better than floury varieties.","Add a fried egg on top if you'd like the traditional presentation, Anna's Oma always did."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the onion and cook, stirring occasionally, until softened and just beginning to colour, about 5 minutes."},{"text":"Add the diced potato and corned beef. Stir to combine and cook for 2 minutes, letting the beef warm through."},{"text":"Pour in the stock and add the bay leaf. Bring to a simmer, then cook uncovered for 12 to 15 minutes, until the potato is tender."},{"text":"Stir in the chopped herring and the herring brine. Cook for another 2 minutes to warm through and let the flavours meld."},{"text":"Taste and adjust seasoning with salt and pepper, remember the herring and brine are already salty."},{"text":"Serve hot in bowls, with dark bread on the side."}],"id":"69832540-38f3-4ecd-8ca0-77a5a1dc448c"},{"notes":["Make the batter up to 2 hours ahead and keep it in the fridge. Shape and fry just before serving.","Don't skip drying the chickpeas, it's what gets them crispy. If they're wet, they'll steam instead."],"steps":[{"text":"Pat the drained chickpeas completely dry with paper towels; this helps them crisp. Mash them roughly in a bowl with a fork, you want some texture, not a smooth paste."},{"text":"Stir through the onion, garlic, parsley, mint, ground coriander, salt and pepper. Add the flour and water and mix until the mixture holds together when squeezed. Let it rest for 5 minutes."},{"text":"With damp hands, shape into 12 flat patties about 6 cm across and 1.5 cm thick. Place on a plate."},{"text":"Heat 60 ml of olive oil in a large heavy-based frying pan over medium-high heat until it shimmers. Working in batches, carefully place 4 fritters into the oil."},{"text":"Fry for 3 to 4 minutes until deep golden and crispy on the first side, then flip and fry for another 3 minutes until the second side is also crispy. Drain on paper towels."},{"text":"Repeat with the remaining fritters, adding more oil to the pan as needed."},{"text":"Serve warm with lemon wedges and extra salt. They're best eaten straight away, while they still crackle."}],"id":"29968c5c-ba25-4194-8859-d0335733bd51"},{"notes":["Make it ahead: braise fully, cool, then refrigerate for up to 2 days. Reheat gently over low heat with a splash of stock.","Swap green olives for kalamata if you prefer, it's richer but still very Tunisian.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"116457e1-7e5b-4bb6-84c0-017d40aa84e9"},{"notes":["Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"8791273a-6245-4bc2-9da9-ccedfebe785c"},{"notes":["Mac salad can be made a few hours ahead and chilled, the flavours improve as it sits.","For a real plate lunch vibe, use a compartment plate. Any firm white rice works; short-grain Japanese-style rice is traditional, but long-grain is just as good.","Prawns cook fast, so watch them carefully. Raw prawns are best, but you can swap in cooked prawns, just heat them through for 1–2 minutes instead.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"a754ed16-1f73-40f2-a12f-513aa2f94374"},{"notes":["Swap the root veg: swede, beetroot or sweet potato all work. Just keep pieces roughly the same size so they cook evenly.","Use bone-in thighs if that's what's in your trolley, just add 5 minutes to the braise time.","Leftovers are even stickier and better the next day. Reheat gently on the stove with a splash of water.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"41317426-5502-47fa-a7ce-a1ee33d59013"},{"notes":["This dish tastes even better the next day. Refrigerate in an airtight container for up to three days, or freeze for a month.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"0813323a-82ef-417d-a2c7-dc34ae065fdc"},{"notes":["The fermentation time depends on your kitchen temperature: warmer rooms will ferment faster (3 days), cooler ones may take 5 days. Taste the batter after day 3, it should be pleasantly sour, not sharp.","Injera freezes well for up to a month. Layer cooked injera between greaseproof paper, wrap tightly, and thaw at room temperature before serving.","Make injera a day or two before you plan to serve it. It stays soft and slightly chewy when wrapped loosely in a clean cloth."],"steps":[{"text":"Mix teff flour, water and salt in a large bowl. Stir until you have a smooth, thin batter with no lumps, thinner than pancake batter, about the consistency of single cream. Cover loosely with a clean cloth."},{"text":"Let the batter ferment at room temperature for 3 to 5 days. It will develop a slightly sour smell and small bubbles will rise to the surface. Stir it down gently each day. You'll know it's ready when it smells pleasantly sour and tastes a little tangy."},{"text":"After fermentation, stir the batter well. It should still be thin and pourable. If it's too thick, add a little warm water, a tablespoon at a time."},{"text":"Heat a large non-stick frying pan or crepe pan (about 30 cm across) over medium-high heat. Don't oil it, injera cooks on a dry surface."},{"text":"Once the pan is hot, pour about 120 ml of batter into the centre. Quickly tilt and swirl the pan so the batter spreads into a thin, even circle that covers the whole base. Work fast, injera sets quickly."},{"text":"Cook for about 1 to 2 minutes without flipping. The top will start to look spongy and develop small holes. The bottom should be light golden and slightly chewy, not crispy. When the steam stops rising, it's done."},{"text":"Slide the injera onto a plate. Repeat with the remaining batter."},{"text":"Stack the finished injera loosely on a plate or cloth to keep them warm and slightly soft."}],"id":"d84d5fd6-2017-46d7-a9af-2b038c8e9e80"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;